<?php
require_once __DIR__.'/../includes/bootstrap.php';
$active='ppmp-submissions';
$userId=(int)(current_user()['id']??0);
$userRole=current_user()['role']??'';$canDeleteDraft=in_array($userRole,[ROLE_ADMIN,ROLE_HEAD_NURSE],true);
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='delete_draft'){
 verify_csrf_token();if(!$canDeleteDraft){http_response_code(403);exit('Access denied.');}
 $id=(int)($_POST['id']??0);$draft=$userRole===ROLE_ADMIN?db_one('SELECT id,ppmp_no FROM procurement_ppmp WHERE id=? AND status="DRAFT"',[$id]):db_one('SELECT id,ppmp_no FROM procurement_ppmp WHERE id=? AND status="DRAFT" AND created_by=?',[$id,$userId]);
 if(!$draft)set_flash('danger','Only an authorized draft PPMP can be deleted.');else{db_statement('DELETE FROM procurement_ppmp WHERE id=? AND status="DRAFT"',[$id]);set_flash('success','Draft PPMP deleted: '.$draft['ppmp_no']);}redirect('ppmp_submissions.php');
}
$rows=db_all('SELECT p.*,d.department_name,(SELECT COUNT(*) FROM procurement_ppmp_items i WHERE i.ppmp_id=p.id) item_count,(SELECT COALESCE(SUM(i.planned_quantity*i.unit_cost),0) FROM procurement_ppmp_items i WHERE i.ppmp_id=p.id) total_cost FROM procurement_ppmp p LEFT JOIN departments d ON d.id=p.department_id WHERE p.created_by=? AND p.status IN("DRAFT","FOR APPROVAL","FOR REVISION") ORDER BY p.updated_at DESC,p.id DESC',[$userId]);
$comments=[];
foreach($rows as$row){$comments[(int)$row['id']]=db_all('SELECT c.review_field,c.comment,c.follow_up_comments,c.resolution_status,c.reviewed_by,c.updated_at,i.item_description FROM procurement_ppmp_review_comments c JOIN procurement_ppmp_items i ON i.id=c.ppmp_item_id WHERE c.ppmp_id=? ORDER BY c.updated_at,c.id',[(int)$row['id']]);foreach($comments[(int)$row['id']] as&$comment){$comment['follow_ups']=json_decode((string)($comment['follow_up_comments']??''),true)?:[];unset($comment['follow_up_comments']);}unset($comment);}
procurement_header('My PPMP Submissions','ppmp-submissions','Manage drafts, track submitted plans, and revise PPMPs returned by reviewers.');
?>
<style>
.submission:not(.has-revision) .submission-comments{display:none}
.submission-list{display:grid;gap:14px}.submission{border:1px solid #d9e5ed;border-radius:8px;background:#fff;overflow:hidden}.submission-head{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 18px;background:#f6f9fb;border-bottom:1px solid #e1e9ee}.submission-title{display:flex;align-items:center;gap:10px;min-width:0}.submission-title strong{color:#123f5a;font-size:15px}.submission-meta{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:12px;padding:14px 18px}.submission-meta span{display:block;margin-bottom:4px;color:#6b7f8d;font-size:10px;font-weight:800;text-transform:uppercase}.submission-comments{padding:0 18px 16px}.submission-comments h3{margin:0 0 9px;color:#294e63;font-size:13px}.comment-list{display:grid;gap:8px}.comment{padding:10px 12px;border-left:3px solid #b7791f;background:#fff8e8;color:#59420e;font-size:12px;line-height:1.45}.comment strong{display:block;margin-bottom:3px}.submission-actions{display:flex;align-items:center;gap:8px;flex-wrap:nowrap}.submission-actions form{display:flex;margin:0}.submission-actions .btn{gap:7px;border-radius:6px}.empty-comments{color:#718493;font-size:12px}.badge.for-revision{background:#ffe4e2;color:#a12b24}@media(max-width:760px){.submission-head{align-items:flex-start;flex-direction:column}.submission-meta{grid-template-columns:repeat(2,1fr)}}
</style>
<section class="panel"><div class="panel-head"><h2>Drafts, Submitted &amp; Returned PPMPs</h2><span class="badge"><?=count($rows)?> active</span></div>
<div class="submission-list">
<?php foreach($rows as$row):?>
<?php $displayStatus=$row['status']==='FOR APPROVAL'&&(int)($row['revision_round']??0)>0?'RESUBMITTED FOR APPROVAL':$row['status'];?>
<article class="submission status-<?=strtolower(str_replace(' ','-',$row['status']))?><?=(int)($row['revision_round']??0)>0?' has-revision':''?>">
 <header class="submission-head"><div class="submission-title"><strong><?=e($row['ppmp_no'])?></strong><span class="badge <?=strtolower(str_replace(' ','-',$displayStatus))?>"><?=e($displayStatus)?></span><small class="ns-next-action">Next: <?=e(nursingWorkflow('ppmp',(string)$row['status'])['next'])?></small></div><div class="submission-actions"><a class="btn light" target="_blank" rel="noopener" href="ppmp_print.php?id=<?=(int)$row['id']?>">Preview</a><?php if($row['status']==='FOR REVISION'):?><a class="btn gold" href="ppmp_create.php?revise=<?=(int)$row['id']?>">Edit &amp; Resubmit</a><?php elseif($row['status']==='DRAFT'):?><a class="btn gold" href="ppmp_create.php?revise=<?=(int)$row['id']?>">Edit Draft</a><?php if($canDeleteDraft):?><form method="post" data-confirm="Permanently delete draft <?=e($row['ppmp_no'])?>? This action cannot be undone."><?=csrf_field()?><input type="hidden" name="action" value="delete_draft"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="btn red" type="submit" title="Delete draft" aria-label="Delete draft <?=e($row['ppmp_no'])?>"><svg xmlns="http://www.w3.org/2000/svg" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18M8 6V4h8v2M19 6l-1 14H6L5 6M10 10v6M14 10v6"/></svg></button></form><?php endif;?><?php endif;?></div></header>
 <div class="submission-meta"><div><span>Year</span><?=e((string)$row['fiscal_year'])?></div><div><span>Unit</span><?=e($row['department_name']??'No department assigned')?></div><div><span>Items</span><?=e((string)$row['item_count'])?></div><div><span>Total Cost</span>₱<?=number_format((float)$row['total_cost'],2)?></div></div>
 <section class="submission-comments"><h3>Reviewer Comments</h3><?php if($comments[(int)$row['id']]):?><div class="comment-list"><?php foreach($comments[(int)$row['id']] as$comment):?><div class="comment"><strong><?=e($comment['item_description'])?></strong><?=e($comment['review_field'])?>: <?=nl2br(e($comment['comment']))?> - <?=e($comment['resolution_status'])?><br><small>By <?=e($comment['reviewed_by'])?></small><?php foreach($comment['follow_ups'] as$index=>$followUp):?><div><strong>Follow-up <?=($index+1)?></strong><?=nl2br(e((string)($followUp['comment']??'')))?><br><small>By <?=e((string)($followUp['reviewed_by']??''))?></small></div><?php endforeach;?></div><?php endforeach;?></div><?php else:?><div class="empty-comments">No reviewer comments yet.</div><?php endif;?></section>
</article>
<?php endforeach;?>
<?php if(!$rows):?><div class="muted">You have no draft, submitted, or returned PPMP.</div><?php endif;?>
</div></section>
<?php procurement_footer(); ?>
